<template>
  <main class="app-container pc-page">
    <h1>我的文件</h1><p class="pc-muted">管理个人资料和成果，按需搜索代码、查看规则与记忆。</p>
    <div class="pc-toolbar"><el-button @click="reload">刷新</el-button><el-button @click="advanced = !advanced">{{advanced ? '收起代码与知识能力' : '代码与知识能力'}}</el-button></div>
    <el-alert v-if="personalContext && !directoryContextId" title="个人执行目录尚未准备" :description="`${personalContext.runtime.message}。资料按本人账号保存，交给助手分析或生成文件时需要可用的执行环境。`" type="warning" :closable="false" />
    <el-alert v-if="contextError || pageError || error" :title="contextError || pageError || error" type="error" :closable="false" /><OperationTask :task-id="operationTaskId" :directory-context-id="directoryContextId" title="建立代码索引" @settled="reload" />
    <el-tabs v-model="activeTab"><el-tab-pane label="文件与成果" name="files"><PersonalFiles @analyse="analyseFile" /></el-tab-pane>
      <el-tab-pane v-if="advanced" label="仓库检索与关系图" name="repository">
        <section class="pc-panel"><div class="pc-toolbar"><el-tag>{{ index ? stateName(index.status) : '无索引' }}</el-tag><span v-if="index" class="pc-muted">版本 {{ index.version }} · {{ index.fileCount ?? '未上报' }} 个文件 · {{ index.embeddingModel || '未配置向量模型' }}</span><el-button v-hasPermi="['paicli:knowledge:manage']" :loading="busy" @click="rebuild">建立 / 重建索引</el-button></div><el-alert v-if="index?.stale" title="索引文件版本已失效，结果须读取当前文件核对。" type="warning" :closable="false" /><el-alert v-if="index?.error" :title="index.error" type="error" :closable="false" /><el-form inline @submit.prevent="search"><el-form-item label="查询内容"><el-input v-model="searchText" placeholder="函数、类型、调用关系或关键词" style="width:320px" /></el-form-item><el-form-item label="搜索方式"><el-select v-model="searchMode" style="width:160px"><el-option label="精确代码搜索" value="EXACT" /><el-option label="语义辅助搜索" value="SEMANTIC" /></el-select></el-form-item><el-form-item><el-button native-type="submit" type="primary" :disabled="!searchText.trim()" :loading="searching">检索仓库</el-button><el-button :disabled="!searchText.trim()" :loading="graphSearching" @click="loadGraph">查看关系图</el-button></el-form-item></el-form><p class="pc-muted">语义索引不可用时仍可精确检索；未配置 embedding 会显示真实错误，不给虚构结果。</p></section>
        <el-alert v-if="searchPending" :title="`检索任务 ${searchPending.taskId}：${searching ? '等待 执行环境 回执' : '本页已停止等待，请在后台任务中核对或稍后重查'}`" type="info" :closable="false" /><el-alert v-if="graphPending" :title="`关系图任务 ${graphPending.taskId}：${graphSearching ? '等待 执行环境 回执' : '本页已停止等待，请在后台任务中核对或稍后重查'}`" type="info" :closable="false" /><section v-if="searched" class="pc-panel"><h2>代码片段与版本</h2><div v-for="(hit,i) in hits" :key="`${hit.file}:${hit.startLine}:${i}`"><strong>{{ hit.file }} · {{ hit.startLine === null ? '行号未上报' : `${hit.startLine}–${hit.endLine ?? '未上报'}` }}</strong><p class="pc-muted">{{ hit.source === 'EXACT' ? '精确匹配' : '语义辅助' }} · 文件哈希 {{ hit.fileHash || '未上报，须读取当前文件核对' }} · 索引版本 {{ hit.indexVersion }}</p><el-alert v-if="hit.stale" title="该片段版本已失效，请重新读取当前文件核对。" type="warning" :closable="false" /><pre class="pc-pre">{{ safeText(hit.snippet) }}</pre></div><el-empty v-if="!hits.length && !searching" description="没有匹配结果" /></section>
        <section v-if="graph" class="pc-panel"><h2>Java AST 关系图</h2><p class="pc-muted">索引版本 {{ graph.indexVersion }}；节点和边来自 执行环境 上报的代码分析。</p><el-alert v-if="graph.stale" title="图中关系版本已失效，需重建索引后核对。" type="warning" :closable="false" /><el-alert v-if="graph.nodes.length > 80" title="图稿只展示前 80 个节点，下方表格保留返回的全部节点与关系。请缩小查询查看局部。" type="info" :closable="false" /><div class="graph-scroll" tabindex="0" aria-label="可滚动代码关系图"><svg :width="graphWidth" :height="graphHeight" role="img" aria-labelledby="pc-graph-title"><title id="pc-graph-title">代码关系图；节点与关系也在下方表格列出</title><defs><marker id="pc-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z" fill="#68768a" /></marker></defs><g v-for="(edge,i) in visibleEdges" :key="i"><line :x1="position(edge.source).x + 85" :y1="position(edge.source).y + 30" :x2="position(edge.target).x + 85" :y2="position(edge.target).y + 30" stroke="#68768a" marker-end="url(#pc-arrow)" /><text :x="(position(edge.source).x + position(edge.target).x) / 2 + 85" :y="(position(edge.source).y + position(edge.target).y) / 2 + 23" font-size="11">{{ edge.type }}</text></g><g v-for="node in visibleNodes" :key="node.id"><rect :x="position(node.id).x" :y="position(node.id).y" width="170" height="60" rx="5" fill="var(--el-color-primary-light-9)" stroke="var(--el-color-primary)" /><text :x="position(node.id).x + 8" :y="position(node.id).y + 22" font-size="12">{{ node.label.slice(0,20) }}</text><text :x="position(node.id).x + 8" :y="position(node.id).y + 42" font-size="11">{{ node.type }} · {{ node.line ?? '行号未上报' }}</text><title>{{ node.label }} · {{ node.file || '文件未上报' }}:{{ node.line ?? '行号未上报' }}</title></g></svg></div><el-collapse><el-collapse-item title="完整节点与关系（可核对文本）"><el-table :data="graph.nodes" max-height="320"><el-table-column prop="label" label="节点" /><el-table-column prop="type" label="类型" width="120" /><el-table-column prop="file" label="代码文件" /><el-table-column prop="line" label="行号" width="90" /></el-table><el-table :data="graph.edges" max-height="320"><el-table-column prop="source" label="来源" /><el-table-column prop="type" label="关系" width="140" /><el-table-column prop="target" label="目标" /></el-table></el-collapse-item></el-collapse></section>
      </el-tab-pane>
      <el-tab-pane v-if="advanced" label="长期记忆与冲突" name="memory"><el-alert title="个人记忆归当前用户所有；目录规则仅用于当前项目的处理，不会与其他用户共享。" type="info" :closable="false" /><el-form inline @submit.prevent="queryMemories"><el-form-item label="范围"><el-select v-model="memoryFilter.scope" style="width:180px"><el-option label="当前目录" value="PROJECT" /><el-option label="当前用户个人偏好" value="PERSONAL" /></el-select></el-form-item><el-form-item label="查找内容"><el-input v-model="memoryFilter.search" /></el-form-item><el-form-item><el-button type="primary" native-type="submit">查询</el-button><el-button v-hasPermi="['paicli:knowledge:manage']" @click="openMemory()">明确记住一条</el-button></el-form-item></el-form><el-table v-loading="memoryLoading" :data="memories"><el-table-column prop="content" label="记忆内容" min-width="300" /><el-table-column label="来源" min-width="180"><template #default="{ row }">{{ memorySourceName(row.source) }}</template></el-table-column><el-table-column label="核实状态" width="150"><template #default="{ row }"><MemoryVerification :memory="row" /></template></el-table-column><el-table-column label="最后核实" min-width="180"><template #default="{ row }">{{ row.status==='VERIFIED' ? displayTime(memoryVerificationTime(row)) : '尚未核实' }}</template></el-table-column><el-table-column label="操作" width="240"><template #default="{ row }"><el-button v-hasPermi="['paicli:knowledge:manage']" link :disabled="busy" @click="verify(row)">核实</el-button><el-button v-hasPermi="['paicli:knowledge:manage']" link @click="openMemory(row)">替换 / 处理冲突</el-button><el-button v-hasPermi="['paicli:knowledge:manage']" link type="danger" :disabled="busy" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-empty v-if="!memoryLoading && !memories.length" description="当前范围没有记忆" /><Pagination v-if="memoryTotal" v-model:page="memoryFilter.pageNum" v-model:limit="memoryFilter.pageSize" :total="memoryTotal" @pagination="loadMemories" /></el-tab-pane>
      <el-tab-pane v-if="advanced" label="PAI 项目规则" name="rules"><ProjectRules :directory-context-id="directoryContextId" /></el-tab-pane><el-tab-pane v-if="advanced" label="提示词覆盖" name="prompts"><PromptTemplates :directory-context-id="directoryContextId" /></el-tab-pane><el-tab-pane v-if="advanced && checkPermi(['paicli:session:read'])" label="会话上下文 / PAI / 提示层" name="context"><div class="pc-toolbar"><label>会话</label><el-select v-model="contextSessionId" style="width:320px" @change="loadContext"><el-option v-for="item in sessions" :key="item.id" :value="item.id" :label="item.title" /></el-select></div><ContextPanel :context="context" :active="contextActive" :readonly="contextReadonly" @refresh="loadContext" /></el-tab-pane>
    </el-tabs>
    <MemoryEditor v-model="memoryOpen" :directory-context-id="directoryContextId" :scope="memoryFilter.scope" :memory="editing" @saved="loadMemories" />
  </main>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { ElMessageBox } from 'element-plus'
import Pagination from '@/components/Pagination/index.vue'
import { deleteMemory, getGraph, getIndex, listMemories, memoryAction, rebuildIndex, searchRepository } from '@/api/paicli/knowledge'
import { getSession, listSessions } from '@/api/paicli/sessions'
import type { PcContext, PcGraph, PcIndex, PcMemory, PcSearchHit, PcSession, PcPendingReceipt } from '@/types/paicli'
import ContextPanel from '../components/ContextPanel.vue'
import PromptTemplates from '../components/PromptTemplates.vue'
import ProjectRules from '../components/ProjectRules.vue'
import MemoryEditor from '../components/MemoryEditor.vue'
import MemoryVerification from '../components/MemoryVerification.vue'
import {memoryVerificationTime} from '../shared/memoryFreshness'
import { checkPermi } from '@/utils/permission'
import OperationTask from '../components/OperationTask.vue'
import { useOperations } from '../useOperations'
import { usePersonalContext } from '../usePersonalContext'
import PersonalFiles from '../components/PersonalFiles.vue'
import {useRouter} from 'vue-router'
import type {PcPersonalFile} from '@/types/paicli'
import { displayTime, errorText, isHistoricalSession, operationKeys, safeText, stateName, terminalTaskStates, memorySourceName } from '../model'
import { awaitKnowledge } from '../knowledgePolling'
import '../page.css'
defineOptions({ name:'PaicliKnowledge' })
const router=useRouter(), personal=usePersonalContext(), directoryContextId=personal.directoryContextId, contextError=personal.error, loadPersonal=personal.load, { busy, error, run } = useOperations(), keys = operationKeys()
const personalContext = personal.context
const activeTab = ref('files'), advanced=ref(false), pageError = ref(''), index = ref<PcIndex | null>(), searchText = ref(''), searchMode = ref<'EXACT'|'SEMANTIC'>('EXACT'), searching = ref(false), searched = ref(false), hits = ref<PcSearchHit[]>([]), graph = ref<PcGraph>(), memories = ref<PcMemory[]>([]), memoryTotal = ref(0), memoryLoading = ref(false), sessions = ref<PcSession[]>([]), contextSessionId = ref(''), context = ref<PcContext>(), contextActive = ref(false), contextReadonly = ref(false), operationTaskId = ref(''), memoryOpen = ref(false), editing = ref<PcMemory>()
const memoryFilter = reactive({ pageNum:1, pageSize:20, scope:'PERSONAL' as 'PROJECT'|'PERSONAL', search:'' })
const searchPending = ref<PcPendingReceipt>(), graphPending = ref<PcPendingReceipt>(), graphSearching = ref(false)
let generation = 0, memoryGeneration = 0, searchGeneration = 0, contextGeneration = 0, graphGeneration = 0, searchController: AbortController | undefined, graphController: AbortController | undefined
const visibleNodes = computed(() => graph.value?.nodes.slice(0,80) ?? []), visibleEdges = computed(() => graph.value?.edges.filter(edge => visibleNodes.value.some(node => node.id === edge.source) && visibleNodes.value.some(node => node.id === edge.target)) ?? [])
const graphWidth = computed(() => Math.min(4,Math.max(1,visibleNodes.value.length)) * 230), graphHeight = computed(() => Math.max(160,Math.ceil(visibleNodes.value.length / 4) * 120))
function position(id: string) { const i = visibleNodes.value.findIndex(node => node.id === id); return { x:20 + (i % 4) * 230, y:30 + Math.floor(i / 4) * 120 } }
const directoryPreparationMessage = '个人执行目录尚未准备，请先准备个人执行环境和目录，再使用当前目录的代码与知识能力。'
function requireDirectory() { if (directoryContextId.value) return true; pageError.value = directoryPreparationMessage; return false }
async function reload() { const id = directoryContextId.value, g = ++generation; pageError.value = ''; const results = await Promise.allSettled([id ? getIndex(id) : Promise.resolve({data:null}), checkPermi(['paicli:session:read']) ? listSessions(id,1,100) : Promise.resolve({rows:[]})]); if (g !== generation || id !== directoryContextId.value) return; const [ir,sr] = results; if (ir.status === 'fulfilled') index.value = ir.value.data; else pageError.value = errorText(ir.reason); if (sr.status === 'fulfilled') sessions.value = sr.value.rows; else pageError.value = [pageError.value,errorText(sr.reason)].filter(Boolean).join('；'); await loadMemories() }
async function search() { if (!requireDirectory() || !searchText.value.trim()) return; searchController?.abort(); const controller = searchController = new AbortController(), g = ++searchGeneration, id = directoryContextId.value, query = searchText.value, mode = searchMode.value; searching.value = true; pageError.value = ''; searched.value = false; searchPending.value = undefined; hits.value = []; try { const result = await awaitKnowledge(() => searchRepository(id,query,mode,controller.signal),controller.signal,receipt => { if (g === searchGeneration) searchPending.value = receipt }); if (g === searchGeneration && id === directoryContextId.value && result !== undefined) { hits.value = result; searched.value = true; searchPending.value = undefined } } catch(cause) { if (g === searchGeneration && !controller.signal.aborted) pageError.value = errorText(cause) } finally { if (g === searchGeneration) searching.value = false } }
async function loadGraph() { if (!requireDirectory()) return; graphController?.abort(); const controller = graphController = new AbortController(), g = ++graphGeneration, id = directoryContextId.value, query = searchText.value; graphSearching.value = true; graphPending.value = undefined; graph.value = undefined; pageError.value = ''; try { const result = await awaitKnowledge(() => getGraph(id,query,controller.signal),controller.signal,receipt => { if (g === graphGeneration) graphPending.value = receipt }); if (g === graphGeneration && id === directoryContextId.value && result !== undefined) { graph.value = result; graphPending.value = undefined } } catch(cause) { if (g === graphGeneration && !controller.signal.aborted) pageError.value = errorText(cause) } finally { if (g === graphGeneration) graphSearching.value = false } }
async function rebuild() { if (!requireDirectory()) return; const id = directoryContextId.value, intent = { action:'index', id }; await run(async () => { operationTaskId.value = (await rebuildIndex(id,keys.get(intent))).data.id; keys.done(intent); await reload() }) }
async function loadMemories() { const g = ++memoryGeneration, id = directoryContextId.value; if (!id && memoryFilter.scope === 'PROJECT') { memories.value = []; memoryTotal.value = 0; memoryLoading.value = false; requireDirectory(); return }; memoryLoading.value = true; try { const response = await listMemories({ ...memoryFilter,directoryContextId:id }); if (g === memoryGeneration && id === directoryContextId.value) { memories.value = response.rows; memoryTotal.value = response.total } } catch(cause) { if (g === memoryGeneration) pageError.value = errorText(cause) } finally { if (g === memoryGeneration) memoryLoading.value = false } }
function queryMemories() { memoryFilter.pageNum = 1; void loadMemories() }
function openMemory(memory?: PcMemory) { if (!checkPermi(['paicli:knowledge:manage'])) return; editing.value = memory; memoryOpen.value = true }
async function verify(entry: PcMemory) { try { await ElMessageBox.confirm(`请已核对来源“${entry.source}”与实际规则后再确认，不能仅采用模型结果。`, '核实记忆', { confirmButtonText:'已核实',cancelButtonText:'返回',type:'warning' }) } catch { return }; const intent = { action:'verify',id:entry.id,version:entry.version }; await run(async () => { await memoryAction(entry.id,'verify',entry.version,entry.content,keys.get(intent)); keys.done(intent); await loadMemories() }) }
async function remove(entry: PcMemory) { try { await ElMessageBox.confirm('仅删除该版本记忆，确认继续？','删除记忆',{ type:'warning' }) } catch { return }; const intent = { action:'delete',id:entry.id,version:entry.version }; await run(async () => { await deleteMemory(entry.id,entry.version,keys.get(intent)); keys.done(intent); await loadMemories() }) }
async function loadContext() { const id = contextSessionId.value, g = ++contextGeneration; if (!id) { context.value = undefined; return }; try { const response = await getSession(id); if (g === contextGeneration && id === contextSessionId.value) { context.value = response.data.context; contextReadonly.value = isHistoricalSession(response.data) || !response.data.runnerId; contextActive.value = !!response.data.activeTaskId && !terminalTaskStates.has(response.data.status) } } catch(cause) { if (g === contextGeneration) pageError.value = errorText(cause) } }
watch(directoryContextId, () => { memoryOpen.value = false; editing.value = undefined; generation++; memoryGeneration++; searchGeneration++; contextGeneration++; graphGeneration++; searchController?.abort(); graphController?.abort(); searching.value = false; graphSearching.value = false; searchPending.value = undefined; graphPending.value = undefined; hits.value = []; graph.value = undefined; index.value = undefined; context.value = undefined; contextReadonly.value = false; operationTaskId.value = ''; contextSessionId.value = ''; memoryFilter.pageNum = 1; searched.value = false; void reload() })
function analyseFile(file:PcPersonalFile){void router.push({path:'/paicli/workbench',query:{fileId:file.id,fileName:file.fileName}})}
onMounted(async () => { await loadPersonal(); if (!directoryContextId.value) await reload() }); onBeforeUnmount(() => { generation++; memoryGeneration++; searchGeneration++; contextGeneration++; graphGeneration++; searchController?.abort(); graphController?.abort() })
</script>
<style scoped>.graph-scroll{max-width:100%;overflow:auto;border:1px solid var(--el-border-color-light);margin-bottom:12px}.graph-scroll text{fill:var(--el-text-color-primary)}.pc-panel + .pc-panel{margin-top:16px}</style>
